TargetContent:
"                       {/* Current Selected Table Indicator Banner */}
                       {orderType === 'DINE_IN' && posSettings.separateView && (
                          <div className={`h-8 px-4 flex items-center justify-between text-[10px] font-black uppercase tracking-wider border-b shrink-0 ${isDark ? 'bg-[#161b22] border-[#30363d] text-white' : 'bg-[#e8f5e9] border-slate-200 text-[#2e7d32]'}`}>
                             <div className="flex items-center gap-1.5">
                                <span className={`w-2 h-2 rounded-full ${selectedTable ? 'bg-[#10ac84] animate-pulse' : 'bg-red-500'}`}></span>
                                <span>ACTIVE TABLE: {selectedTable ? selectedTable.table_name : 'NONE (Select a table from top)'}</span>
                             </div>
                             {selectedTable && (
                                <button onClick={() => { setSelectedTable(null); setCart([]); }} className="text-[9px] text-red-500 hover:text-red-600 transition-colors uppercase font-black">Clear Selection</button>
                             )}
                          </div>
                       )}"
